def solve_small(n):
    # Black squares: (i,j) with i+j even, 1 <= i,j <= n
    black_squares = []
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if (i + j) % 2 == 0:
                black_squares.append((i, j))

    # Bipartite graph
    # S1: i,j are both odd
    # S2: i,j are both even
    S1 = []
    S2 = []
    for (i, j) in black_squares:
        if i % 2 == 1:
            S1.append((i, j))
        else:
            S2.append((i, j))

    # Edges between S1 and S2
    adj = {v: [] for v in S1}
    for (i, j) in S2:
        for di in [-1, 1]:
            for dj in [-1, 1]:
                ni, nj = i + di, j + dj
                if (ni, nj) in adj:
                    adj[(ni, nj)].append((i, j))
                    # This is slightly wrong. Let's fix the adjacency.

    # Let's re-do adjacency properly
    adj = {v: [] for v in S1}
    for (i, j) in S2:
        for ni in [i-1, i+1]:
            for nj in [j-1, j+1]:
                if (ni, nj) in adj:
                    adj[(ni, nj)].append((i, j))

    # Maximum matching in bipartite graph
    match = {}
    def can_match(u, visited):
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                if v not in match or can_match(match[v], visited):
                    match[v] = u
                    return True
        return False

    matching_size = 0
    # Wait, the adjacency is between S1 and S2.
    # Let's make it: for each v in S1, its neighbors are in S2.
    adj_correct = {v: [] for v in S1}
    for (i, j) in S1:
        for di in [-1, 1]:
            for dj in [-1, 1]:
                ni, nj = i + di, j + dj
                if (ni, nj) in S2:
                    adj_correct[(i, j)].append((ni, nj))

    match = {}
    matching_size = 0
    for u in S1:
        visited = set()
        def dfs(u_curr, visited_curr):
            for v in adj_correct[u_curr]:
                if v not in visited_curr:
                    visited_curr.add(v)
                    if v not in match or dfs(match[v], visited_curr):
                        match[v] = u_curr
                        return True
            return False

        if dfs(u, visited):
            matching_size += 1

    N = len(black_squares)
    min_trominos = N - matching_size
    return min_trominos, len(S1)

for n in range(1, 9, 2):
    res, s1_size = solve_small(n)
    print(f"n={n}, min_trominos={res}, |S1|={s1_size}")
